function converterDados(){const e=parseFloat(document.getElementById("input-valor").value),t=document.getElementById("select-unidade").value,a=document.getElementById("resultado-binario"),r=document.getElementById("resultado-decimal");if(isNaN(e))return;const n={B:1,KiB:1024,MiB:1024**2,GiB:1024**3,TiB:1024**4},s={B:1,kB:1e3,MB:1e6,GB:1e9,TB:1e12},c=e*n[t.replace("k","Ki").replace("M","Mi").replace("G","Gi").replace("T","Ti")||t];let o="<h4>Padrão Binário (IEC)</h4>";for(let e in n){let t=c/n[e];o+=`<p><strong>${t.toLocaleString("pt-BR")}</strong> ${e}</p>`}const l=e*(s[t]||1);let i="<h4>Padrão Decimal (SI)</h4>";for(let e in s){let t=l/s[e];i+=`<p><strong>${t.toLocaleString("pt-BR")}</strong> ${e}</p>`}a.innerHTML=o,r.innerHTML=i}